import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String data = scanner.nextLine();
        String part1 = data.substring(0, 1) + data.substring(1).replaceFirst("at", "@");
        String part2 = part1.substring(0, 1) + part1.substring(1, part1.length() - 1).replace("dot", ".") + part1.substring(part1.length() - 1);
        System.out.println(part2);
        scanner.close();
    }
}
